    /// <summary>
    /// 127 AFS turrets on 24 maps, one on each mount the client's maps build for one - the standard
    /// turret's platform, the light turret's tripod or track - that is not a ruin and not a control
    /// point's. By zone:
    /// Abyss 7, Ashen Desert 5, Bootcamp 1, Crucible 5, Descent 4, Divide 10, Earth 4, Howling Maw
    /// 13, Incline 7, Marshes 5, Mires 5, Palisades 8, Plains 17, Plateau 13, Pools 2, Thunderhead
    /// 12, Wilderness 9.
    /// Height: the mount's plus the median of the designers' own destroyed
    /// turrets over theirs (+2.56 platform, +1.05 tripod, +1.03 track), which is where the gun stands;
    /// an emplacement is kept exactly there. Respawn 300 s. turret_mounts.csv has every mount, the
    /// 56 left out and why.
    /// </summary>
    public class TurretSpawnpoolPreloader : PreloaderBase, IPreloader
    {
        public void Preload(MigrationBuilder migrationBuilder)
        {
            Insert(migrationBuilder, SpawnPoolEntry.TableName, typeof(SpawnPoolEntry));
        }

